  { imie: "Tomek", wiek: 19 },
  { imie: "Zosia", wiek: 16 }
];

console.log(pracownicy.filter(p => p.wiek >= 18));
// [{ imie: 'Marta', wiek: 34 }, { imie: 'Tomek', wiek: 19 }]

