];

console.log(pracownicy.filter(p => p.dzial === "IT"));
// [{ imie: 'Marta', dzial: 'IT' }, { imie: 'Ola', dzial: 'IT' }]

const produkty = [
  { nazwa: "Kubek", cena: 25, dostepny: true },
  { nazwa: "Laptop", cena: 3000, dostepny: true },
  { nazwa: "Notes", cena: 15, dostepny: false }
];

console.log(produkty.filter(p => p.dostepny && p.cena < 200));
// [{ nazwa: 'Kubek', cena: 25, dostepny: true }]

function sprawdzPusty(tablicaWynikow) {
  if (tablicaWynikow.length === 0) {
    return "brak wynikow";
  }
  return `znaleziono ${tablicaWynikow.length} wynikow`;
}

const temperatury = [15, 22, 8, 30];
console.log(sprawdzPusty(temperatury.filter(t => t > 100))); // "brak wynikow"
console.log(sprawdzPusty(temperatury.filter(t => t > 10)));  // "znaleziono 3 wynikow"

const zamowienia = [
  { id: 1, status: "nowe" },
  { id: 2, status: "zrealizowane" },
  { id: 3, status: "nowe" },
  { id: 4, status: "nowe" }
];

const nowe = zamowienia.filter(z => z.status === "nowe");
console.log(nowe.length); // 3

const produkty = [
  { nazwa: "Kubek", cena: 25 },
  { nazwa: "Buty", cena: 150 },
  { nazwa: "Laptop", cena: 3000 },
  { nazwa: "Notes", cena: 55 },
  { nazwa: "Plecak", cena: 200 }
];

console.log(produkty.filter(p => p.cena >= 50 && p.cena <= 200));
// [{ nazwa: 'Buty', cena: 150 }, { nazwa: 'Notes', cena: 55 }, { nazwa: 'Plecak', cena: 200 }]

const uzytkownicy = [
  { imie: "Jan", aktywny: true },
  { imie: "Ala", aktywny: false },
  { imie: "Kuba", aktywny: false }
];

console.log(uzytkownicy.filter(u => !u.aktywny));
// [{ imie: 'Ala', aktywny: false }, { imie: 'Kuba', aktywny: false }]

const produkty = [
  { nazwa: "Kubek", kategoria: "agd" },
  { nazwa: "Koszula", kategoria: "odziez" },
  { nazwa: "Notes", kategoria: "biuro" }
];

console.log(produkty.filter(p => p.kategoria !== "odziez"));
// [{ nazwa: 'Kubek', kategoria: 'agd' }, { nazwa: 'Notes', kategoria: 'biuro' }]

const dozwoloneKategorie = ["elektronika", "ksiazki"];
const produkty = [
  { nazwa: "Laptop", kategoria: "elektronika" },
  { nazwa: "Koszula", kategoria: "odziez" },
  { nazwa: "Powiesc", kategoria: "ksiazki" }
];

console.log(produkty.filter(p => dozwoloneKategorie.includes(p.kategoria)));
// [{ nazwa: 'Laptop', ... }, { nazwa: 'Powiesc', ... }]

function policzSpelniajace(tablica, predykat) {
  return tablica.filter(predykat).length;
}

const liczby = [1, 6, 3, 8, 2, 9];
console.log(policzSpelniajace(liczby, n => n > 5)); // 3

const zamowienia = [
  { id: 1, status: "zrealizowane", kwota: 250 },
  { id: 2, status: "nowe", kwota: 500 },
  { id: 3, status: "zrealizowane", kwota: 50 }
];

console.log(zamowienia.filter(z => z.status === "zrealizowane" && z.kwota > 100));
// [{ id: 1, status: 'zrealizowane', kwota: 250 }]

const studenci = [
  { imie: "Kasia", srednia: 4.8 },
  { imie: "Wyjatek", srednia: 3.0 },
  { imie: "Tomek", srednia: 3.5 }
];

console.log(studenci.filter(s => s.srednia >= 4.5 || s.imie === "Wyjatek"));
// [{ imie: 'Kasia', srednia: 4.8 }, { imie: 'Wyjatek', srednia: 3.0 }]

const liczby = [10, 20, 30, 40, 50];
const wynik = liczby.filter(n => n !== 30);
console.log(wynik.length); // 4
console.log(wynik);        // [10, 20, 40, 50]

const ksiazki = [
  { tytul: "Lalka", autor: "Prus", rokWydania: 1890 },
  { tytul: "Blade Runner: Nowy Poczatek", autor: "X", rokWydania: 2019 },
  { tytul: "Solaris", autor: "Lem", rokWydania: 1961 }
];

console.log(ksiazki.filter(k => k.rokWydania > 2000));
// [{ tytul: 'Blade Runner: Nowy Poczatek', autor: 'X', rokWydania: 2019 }]

